mapper.select:
select cs.id, cs.course_id, c.course_name, cs.credits_type, cs.number from course_section cs left join course c on c.id = cs.course_id
cs.status = 3
and c.dept_id = (select dept_id from teacher where id = #{teacherId})
and cs.course_id = #{courseId}
and c.course_name like concat('%', #{courseName}, '%')
and cs.credits_type = #{creditsType}

select cs.id, cs.course_id, c.course_name, c.credits, cs.teacher_id , t.name as teacher_name, cs.credits_type,
       cs.place, cs.number, cs.current_students, cs.status, cs.semester, cs.course_total, cs.course_time, cs.course_number, cs.created_time
from course_section cs
left join teacher t on t.id = cs.teacher_id
left join course c on c.id = cs.course_id

    cs.status != 3

        and cs.course_id = #{courseId}


        and c.course_name like concat('%', #{courseName}, '%')


        and cs.credits_type = #{creditsType}


        and cs.teacher_id = #{teacherId}


        and t.name like concat('%', #{teacherName}, '%')


        and cs.semester like concat('%', #{semester}, '%')


        and cs.status = #{status}

select c.course_name, cs.place, cs.course_total, cs.course_time, cs.course_number
from course_section cs
    left join course c on c.id = cs.course_id
where cs.teacher_id = #{teacherId}
  and cs.status != 3
  and cs.semester = #{semester}

mapper.update:
update course_section
set credits_type = #{creditsType},
    number       = #{number}
where course_id = #{courseId}
and status = '3'

update course_section
teacher_id = #{teacherId}, place = #{place}, number = #{number}, semester = #{semester}, current_students = #{currentStudents}, status = #{status},
course_time = #{courseTime},
course_total = #{courseTotal},
course_number = #{courseNumber}
where id = #{id}

mapper.select:
SELECT EXISTS (
    SELECT 1 FROM teacher t, course c
    WHERE t.id = #{teacherId}
      AND c.id = #{courseId}
      AND t.dept_id = c.dept_id
) AS is_match

select (current_students < number) as has_capacity
from course_section
where id = #{courseId}

select exists(select 1
              from student_section
              where student_id = #{studentId}
                and scourse_id = #{courseId}
              limit 1)

select exists(
    select 1
    from student_section ss
    join course_section cs on ss.scourse_id = cs.id
    join course c on cs.course_id = c.id
    where ss.student_id = #{studentId}
      and c.course_name = (
          select c2.course_name
          from course_section cs2
          join course c2 on cs2.course_id = c2.id
          where cs2.id = #{courseId}
      )
      and cs.id != #{courseId}
    limit 1
)

mapper.delete:
delete from student_section
where student_id = #{studentId}
  and scourse_id = #{courseId}

mapper.update:
update course_section
set current_students = current_students + #{count}
where id = #{courseId}

update course_section
set status = #{status}
where id = #{id}
